import numpy as np
import pandas as pd
from datetime import datetime, timedelta

def generate_site(context):
    rng = np.random.default_rng(context["seed"])
    site_id = context["your_site"]["site_id"]
    n_patients = context["your_site"]["n_patients"]
    start_p_num = context["your_site"]["first_patient_number"]

    # 1. Randomization Arms (Permuted Blocks of 4)
    patient_ids = [f"P{start_p_num + i:04}" for i in range(n_patients)]
    arms = []
    for _ in range(n_patients // 4):
        block = ["drug", "drug", "placebo", "placebo"]
        rng.shuffle(block)
        arms.extend(block)

    ground_truth = [{"patient_id": pid, "arm": arm} for pid, arm in zip(patient_ids, arms)]
    patient_arm_map = {pid: arm for pid, arm in zip(patient_ids, arms)}

    # 2. Patients Table
    patients = []
    for i, pid in enumerate(patient_ids):
        age = int(rng.normal(58.5, 9.5))
        age = max(30, min(75, age))
        sex = "F" if rng.random() < 0.446 else "M"
        bmi = max(19.5, min(67.4, rng.normal(33.18, 7.71)))
        baseline_hba1c = max(7.0, min(10.5, rng.normal(8.12, 0.96)))
        patients.append({
            "patient_id": pid, "site_id": site_id, "age": age, "sex": sex, 
            "bmi": bmi, "baseline_hba1c": baseline_hba1c
        })

    # 3. Visits and Longitudinal Logic
    visits = []
    labs = []
    vitals = []
    dispensing = []

    visit_names = [
        ("Screening", -14, "SCR"), ("Baseline", 0, "BL"), ("Week 2", 14, "W02"),
        ("Week 4", 28, "W04"), ("Week 8", 56, "W08"), ("Week 12", 84, "W12"),
        ("Week 16", 112, "W16"), ("Week 20", 140, "W20"), ("Week 24", 168, "W24")
    ]

    for p_idx, p_data in enumerate(patients):
        pid = p_data["patient_id"]
        arm = patient_arm_map[pid]

        # Start date within enrollment window
        enroll_start = datetime.strptime(context["your_site"]["enrollment_window"][0], "%Y-%m-%d")
        enroll_end = datetime.strptime(context["your_site"]["enrollment_window"][1], "%Y-%m-%d")
        days_range = (enroll_end - enroll_start).days
        bl_date = enroll_start + timedelta(days=rng.integers(0, days_range))

        # Dropout logic
        completes = rng.random() < context["rates"]["completed_week24_share"]
        max_visit_idx = len(visit_names) if completes else rng.integers(3, len(visit_names))

        prev_kit_id = None

        for v_idx, (v_name, offset, v_code) in enumerate(visit_names[:max_visit_idx]):
            if v_idx > 0 and rng.random() < context["rates"]["missed_scheduled_visit_rate"]:
                continue

            v_date = bl_date + timedelta(days=offset + rng.integers(-3, 4))
            v_id = f"V{pid[1:]}-{v_code}"

            visits.append({
                "visit_id": v_id, "patient_id": pid, "visit_name": v_name,
                "date": v_date.strftime("%Y-%m-%d"), "scheduled": True
            })

            # Vitals
            weight = max(42.9, min(206.5, p_data["bmi"] * 2.8 + rng.normal(0, 2)))
            vitals.append({
                "visit_id": v_id, "sbp": int(rng.normal(129, 15)), 
                "dbp": int(rng.normal(75, 8)), "weight": round(weight, 1)
            })

            # Labs (Correlated HbA1c and Glucose)
            # Drug effect: -0.8% reduction over 24 weeks; Placebo: +0.1% drift
            progression = offset / 168.0
            if arm == "drug":
                current_hba1c = p_data["baseline_hba1c"] - (0.8 * progression) + rng.normal(0, 0.2)
            else:
                current_hba1c = p_data["baseline_hba1c"] + (0.1 * progression) + rng.normal(0, 0.2)

            # HbA1c - central only
            if v_name in context["protocol"]["central_lab_visits"]:
                labs.append({
                    "lab_id": f"L-{v_id}-H", "visit_id": v_id, "test": "hba1c",
                    "value": round(current_hba1c, 1), "source": "central", "draw_time": "08:30"
                })
                # Fasting Glucose - central
                gl_val = current_hba1c * 28.7 - 46.7 + rng.normal(0, 10)
                labs.append({
                    "lab_id": f"L-{v_id}-GF", "visit_id": v_id, "test": "glucose_fasting",
                    "value": round(max(78, min(304, gl_val)), 1), "source": "central", "draw_time": "08:35"
                })

            # Local Lab (Fingerstick) - all visits from BL
            if v_idx >= 1:
                fs_gl = current_hba1c * 28.7 - 46.7 + rng.normal(0, 15)
                labs.append({
                    "lab_id": f"L-{v_id}-FS", "visit_id": v_id, "test": "glucose_fingerstick",
                    "value": round(max(57, min(341, fs_gl)), 1), "source": "local", "draw_time": "08:45"
                })

            # Dispensing
            if v_name in context["protocol"]["dispense_visits"]:
                # Return previous kit
                if prev_kit_id:
                    dispensing.append({
                        "event_id": f"RET-{v_id}", "patient_id": pid, "date": v_date.strftime("%Y-%m-%d"),
                        "kit_id": prev_kit_id, "event_type": "return"
                    })
                # Dispense new kit
                new_kit_id = f"K{rng.integers(10000, 99999)}"
                dispensing.append({
                    "event_id": f"DISP-{v_id}", "patient_id": pid, "date": v_date.strftime("%Y-%m-%d"),
                    "kit_id": new_kit_id, "event_type": "dispense"
                })
                prev_kit_id = new_kit_id

            # Final return at Week 24
            if v_name == "Week 24" and prev_kit_id:
                dispensing.append({
                    "event_id": f"RET-FINAL-{v_id}", "patient_id": pid, "date": v_date.strftime("%Y-%m-%d"),
                    "kit_id": prev_kit_id, "event_type": "return"
                })

    # 4. Adverse Events
    adverse_events = []
    ae_terms = context["rates"]["adverse_event_terms"]
    ae_map = {
        "Nausea": "GI", "Diarrhoea": "GI", "Headache": "Nervous system", 
        "Dizziness": "Nervous system", "Nasopharyngitis": "Infection",
        "Fatigue": "General", "Arthralgia": "Musculoskeletal", "Back pain": "Musculoskeletal"
    }

    for pid in patient_ids:
        if rng.random() < context["rates"]["adverse_events_per_patient"]:
            term = rng.choice(list(ae_terms.keys()))
            onset_offset = rng.integers(10, 160)
            onset_date = (datetime.strptime(patients[0]["site_id"], "S21") or enroll_start) # dummy use of site_id
            # Re-calculating start for the specific patient
            p_bl_date = datetime.strptime([v["date"] for v in visits if v["patient_id"] == pid and v["visit_name"] == "Baseline"][0], "%Y-%m-%d")
            onset_dt = p_bl_date + timedelta(days=onset_offset)

            adverse_events.append({
                "ae_id": f"AE-{pid}-{rng.integers(100, 999)}", "patient_id": pid,
                "term": term, "category": ae_map[term], "onset_date": onset_dt.strftime("%Y-%m-%d"),
                "severity": rng.choice(["mild", "moderate", "severe"], p=[0.718, 0.245, 0.037])
            })

    # 5. Conmeds
    conmeds = []
    classes = context["rates"]["conmed_patient_share"]
    for pid in patient_ids:
        for cls, share in classes.items():
            if rng.random() < share:
                conmeds.append({
                    "patient_id": pid, "drug_class": cls, "start_date": "2025-12-01"
                })

    # 6. Kit Storage
    kit_storage = []
    unique_kits = list(set([d["kit_id"] for d in dispensing]))
    for kit in unique_kits:
        kit_storage.append({
            "event_id": f"STR-{kit}", "patient_id": next(d["patient_id"] for d in dispensing if d["kit_id"] == kit),
            "kit_id": kit, "date": "2025-12-20", "event_type": "received",
            "storage": "refrigerated", "temp_c": round(rng.normal(7.4, 1.5), 1)
        })

    return {
        "patients": patients,
        "visits": visits,
        "labs": labs,
        "vitals": vitals,
        "adverse_events": adverse_events,
        "conmeds": conmeds,
        "dispensing": dispensing,
        "kit_storage": kit_storage,
        "ground_truth": ground_truth
    }

