    patient_arm_map = {pid: arm for pid, arm in zip(patient_ids, arms)}

    # 2. Patients Table
    patients = []
    for i, pid in enumerate(patient_ids):
        age = int(rng.normal(58.51, 9.56))
        age = max(30, min(75, age))
        sex = "F" if rng.random() < 0.446 else "M"
        bmi = max(19.5, min(67.4, rng.normal(33.18, 7.71)))
        baseline_hba1c = max(7.0, min(10.5, rng.normal(8.12, 0.96)))
        patients.append({
            "patient_id": pid, "site_id": site_id, "age": age, "sex": sex, 
            "bmi": bmi, "baseline_hba1c": baseline_hba1c
        })

    # 3. Visits and Longitudinal Logic
    visits = []
    labs = []
    vitals = []
    dispensing = []

    visit_names = [
        ("Screening", -14, "SCR"), ("Baseline", 0, "BL"), ("Week 2", 14, "W02"),
        ("Week 4", 28, "W04"), ("Week 8", 56, "W08"), ("Week 12", 84, "W12"),
        ("Week 16", 112, "W16"), ("Week 20", 140, "W20"), ("Week 24", 168, "W24")
    ]

    for p_data in patients:
        pid = p_data["patient_id"]
        arm = patient_arm_map[pid]

        # Enrollment and baseline date
        enroll_start = datetime.strptime(context["your_site"]["enrollment_window"][0], "%Y-%m-%d")
        enroll_end = datetime.strptime(context["your_site"]["enrollment_window"][1], "%Y-%m-%d")
        days_range = (enroll_end - enroll_start).days
        bl_date = enroll_start + timedelta(days=int(rng.integers(0, days_range)))

        completes = rng.random() < context["rates"]["completed_week24_share"]
        max_visit_idx = len(visit_names) if completes else int(rng.integers(2, len(visit_names)))

        prev_kit_id = None

        for v_idx, (v_name, offset, v_code) in enumerate(visit_names[:max_visit_idx]):
            # Missed visit logic (skip random visits, excluding SCR, BL, W24)
            if v_idx > 1 and v_name != "Week 24" and rng.random() < context["rates"]["missed_scheduled_visit_rate"]:
                continue

            # Fix: cast numpy int64 to standard python int for timedelta
            v_date = bl_date + timedelta(days=int(offset + rng.integers(-3, 4)))
            v_id = f"V{pid[1:]}-{v_code}"

            visits.append({
                "visit_id": v_id, "patient_id": pid, "visit_name": v_name,
                "date": v_date.strftime("%Y-%m-%d"), "scheduled": True
            })

            # Vitals
            weight_val = p_data["bmi"] * 2.8 + rng.normal(0, 0.5)
            vitals.append({
                "visit_id": v_id, "sbp": int(rng.normal(129.19, 15)), 
                "dbp": int(rng.normal(74.84, 8)), "weight": round(max(42.9, min(206.5, weight_val)), 1)
            })

            # Lab progression: Drug (-0.5% HbA1c), Placebo (+0.3% HbA1c)
            prog = offset / 168.0
            if arm == "drug":
                cur_hba1c = p_data["baseline_hba1c"] - (0.5 * prog) + rng.normal(0, 0.2)
            else:
                cur_hba1c = p_data["baseline_hba1c"] + (0.3 * prog) + rng.normal(0, 0.2)

            # Central Labs (SCR, BL, W12, W24)
            if v_name in context["protocol"]["central_lab_visits"]:
                labs.append({
                    "lab_id": f"L-{v_id}-H", "visit_id": v_id, "test": "hba1c",
                    "value": round(cur_hba1c, 1), "source": "central", "draw_time": "08:30"
                })
                gl_val = cur_hba1c * 28.7 - 46.7 + rng.normal(0, 10)
                labs.append({
                    "lab_id": f"L-{v_id}-GF", "visit_id": v_id, "test": "glucose_fasting",
                    "value": round(max(78, min(304, gl_val)), 1), "source": "central", "draw_time": "08:35"
                })

            # Local Lab (Fingerstick) from Baseline onwards
            if v_idx >= 1:
                fs_gl = cur_hba1c * 28.7 - 46.7 + rng.normal(0, 15)
                labs.append({
                    "lab_id": f"L-{v_id}-FS", "visit_id": v_id, "test": "glucose_fingerstick",
                    "value": round(max(57, min(341, fs_gl)), 1), "source": "local", "draw_time": "08:45"
                })

            # Dispensing Logic
            if v_name in context["protocol"]["dispense_visits"]:
                if prev_kit_id:
                    dispensing.append({
                        "event_id": f"RET-{v_id}", "patient_id": pid, "date": v_date.strftime("%Y-%m-%d"),
                        "kit_id": prev_kit_id, "event_type": "return"
                    })
                new_kit_id = f"K{rng.integers(10000, 99999)}"
                dispensing.append({
                    "event_id": f"DISP-{v_id}", "patient_id": pid, "date": v_date.strftime("%Y-%m-%d"),
                    "kit_id": new_kit_id, "event_type": "dispense"
                })
                prev_kit_id = new_kit_id

            # Return at W24 if kit is outstanding
            if v_name == "Week 24" and prev_kit_id:
                dispensing.append({
                    "event_id": f"RET-FINAL-{v_id}", "patient_id": pid, "date": v_date.strftime("%Y-%m-%d"),
                    "kit_id": prev_kit_id, "event_type": "return"
                })

    # 4. Adverse Events
    adverse_events = []
    ae_map = {
        "Nausea": "GI", "Diarrhoea": "GI", "Headache": "Nervous system", 
        "Dizziness": "Nervous system", "Nasopharyngitis": "Infection",
        "Fatigue": "General", "Arthralgia": "Musculoskeletal", "Back pain": "Musculoskeletal"
    }
    ae_terms_info = context["rates"]["adverse_event_terms"]
    terms = list(ae_terms_info.keys())
    weights = np.array(list(ae_terms_info.values()))
    weights /= weights.sum()

    for pid in patient_ids:
        if rng.random() < context["rates"]["adverse_events_per_patient"]:
            p_bl_dates = [v["date"] for v in visits if v["patient_id"] == pid and v["visit_name"] == "Baseline"]
            if p_bl_dates:
                p_bl_dt = datetime.strptime(p_bl_dates[0], "%Y-%m-%d")
                # Fix: cast numpy int to python int for AE onset
                onset_dt = p_bl_dt + timedelta(days=int(rng.integers(5, 160)))
                term = rng.choice(terms, p=weights)
                adverse_events.append({
                    "ae_id": f"AE-{pid}-{rng.integers(100, 999)}", "patient_id": pid,
                    "term": term, "category": ae_map[term], "onset_date": onset_dt.strftime("%Y-%m-%d"),
                    "severity": rng.choice(["mild", "moderate", "severe"], p=[0.718, 0.245, 0.037])
                })

    # 5. Conmeds (Pre-existing)
    conmeds = []
    for pid in patient_ids:
        for cls, share in context["rates"]["conmed_patient_share"].items():
            if rng.random() < share:
                conmeds.append({
                    "patient_id": pid, "drug_class": cls, "start_date": "2025-12-01"
                })

    # 6. Kit Storage
    kit_storage = []
    unique_kits = list(set([d["kit_id"] for d in dispensing]))
    for kit in unique_kits:
        k_pid = next(d["patient_id"] for d in dispensing if d["kit_id"] == kit)
        kit_storage.append({
            "event_id": f"STR-{kit}", "patient_id": k_pid, "kit_id": kit,
            "date": "2025-12-20", "event_type": "received", "storage": "refrigerated",
            "temp_c": round(rng.normal(7.43, 1.5), 1)
        })

    return {
        "patients": patients,
        "visits": visits,
        "labs": labs,
        "vitals": vitals,
        "adverse_events": adverse_events,
        "conmeds": conmeds,
        "dispensing": dispensing,
        "kit_storage": kit_storage,
        "ground_truth": ground_truth
    }
